import { cookies, headers } from 'next/headers'

const DEFAULT_THEME = 'light'
const DEFAULT_LANGUAGE = 'en'

/**
 * Picks the highest-priority language tag out of an Accept-Language header,
 * e.g. `fr-CH,fr;q=0.9,en;q=0.8` -> `fr-CH`. Falls back to `en` when the
 * header is missing, empty, or only contains the `*` wildcard.
 */
function parseAcceptLanguage(header: string | null): string {
  if (!header) return DEFAULT_LANGUAGE

  const preferred = header
    .split(',')
    .map((part, index) => {
      const [tag, ...params] = part.split(';').map((piece) => piece.trim())
      const qParam = params.find((param) => param.startsWith('q='))
      const quality = qParam ? Number.parseFloat(qParam.slice(2)) : 1

      return {
        tag,
        // A malformed q value is treated as the lowest possible priority.
        quality: Number.isNaN(quality) ? 0 : quality,
        index,
      }
    })
    .filter((entry) => entry.tag !== '' && entry.tag !== '*' && entry.quality > 0)
    // Equal q values keep the order they were sent in.
    .sort((a, b) => b.quality - a.quality || a.index - b.index)[0]

  return preferred?.tag ?? DEFAULT_LANGUAGE
}

export default async function Preferences() {
  const [cookieStore, headerList] = await Promise.all([cookies(), headers()])

  const theme = cookieStore.get('theme')?.value || DEFAULT_THEME
  const language = parseAcceptLanguage(headerList.get('accept-language'))

  return (
    <section>
      <h2>Preferences</h2>
      <dl>
        <dt>Theme</dt>
        <dd data-testid="theme">{theme}</dd>
        <dt>Language</dt>
        <dd data-testid="language">{language}</dd>
      </dl>
    </section>
  )
}

